// EDUVERSE chunk: C — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_C = [{"bahas":"Babak merupakan bagian dari pertandingan, sama seperti bab merupakan bagian dari buku. Pasangan lain menunjukkan hubungan orang dengan tempat, penghargaan dengan penerima, orang dengan alat yang dipakai, dan suara dengan sumber suara, bukan hubungan bagian dengan keseluruhan.","id":"CPU01","kunci":1,"opsi":["Penonton : Stadion","Bab : Buku","Medali : Pemenang","Wasit : Peluit","Sorak : Penonton"],"soal":"Babak : Pertandingan = ... Pilihlah pasangan kata yang hubungannya sama dengan hubungan kedua kata tersebut.","subtes":"Penalaran Umum"},{"bahas":"Semua penari Sanggar Melati mengikuti latihan olah tubuh setiap pekan, dan semua anggota baru sanggar itu adalah penari Sanggar Melati, sehingga semua anggota baru juga mengikuti latihan olah tubuh setiap pekan. Pernyataan lain bertentangan dengan premis atau membalik hubungan yang dinyatakan premis.","id":"CPU02","kunci":3,"opsi":["Sebagian anggota baru tidak mengikuti latihan olah tubuh setiap pekan.","Semua orang yang mengikuti latihan olah tubuh adalah anggota baru sanggar itu.","Tidak ada penari Sanggar Melati yang merupakan anggota baru.","Semua anggota baru sanggar itu mengikuti latihan olah tubuh setiap pekan.","Sebagian penari Sanggar Melati tidak mengikuti latihan olah tubuh setiap pekan."],"soal":"Perhatikan dua premis berikut. Premis 1: Semua penari Sanggar Melati mengikuti latihan olah tubuh setiap pekan. Premis 2: Semua anggota baru sanggar itu adalah penari Sanggar Melati. Manakah kesimpulan yang tepat berdasarkan kedua premis tersebut?","subtes":"Penalaran Umum"},{"bahas":"Gita tampil di antara Fajar dan Hadi, sedangkan Fajar tampil sebelum Hadi, sehingga urutan tampil ketiganya adalah Fajar, lalu Gita, lalu Hadi. Dewi tampil pada urutan terakhir dan Intan tidak tampil pada urutan paling awal. Susunan yang memenuhi semua syarat hanya menempatkan Fajar pada urutan paling awal, sedangkan posisi Gita, Hadi, dan Intan dapat berubah.","id":"CPU03","kunci":0,"opsi":["Fajar tampil pada urutan pertama.","Gita tampil pada urutan kedua.","Hadi tampil pada urutan ketiga.","Intan tampil pada urutan ketiga.","Intan tampil tepat setelah Fajar."],"soal":"Lima penampil, yaitu Dewi, Fajar, Gita, Hadi, dan Intan, tampil berurutan pada urutan 1 (paling awal) sampai urutan 5 (paling akhir) dalam sebuah festival seni. Diketahui: Fajar tampil sebelum Hadi; Gita tampil di antara Fajar dan Hadi; Dewi tampil pada urutan terakhir; Intan tidak tampil pada urutan pertama. Manakah pernyataan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Selisih antara bilangan yang berurutan adalah 3, 5, 7, dan 9, sehingga selisih bertambah 2 setiap langkah. Selisih berikutnya adalah 11 sehingga bilangan berikutnya adalah 28 ditambah 11, yaitu 39.","id":"CPU04","kunci":4,"opsi":["35","37","38","41","39"],"soal":"Perhatikan pola bilangan berikut: 4, 7, 12, 19, 28, ... Bilangan berikutnya dalam pola tersebut adalah ...","subtes":"Penalaran Umum"},{"bahas":"Aturan sanggar mewajibkan setiap peserta kelas tari lanjutan sudah lulus ujian dasar dan membawa kostum latihan. Sari mengikuti kelas tari lanjutan, sehingga syarat tersebut berlaku untuk Sari. Hal lain seperti waktu kelulusan, jumlah kelas yang diikuti, penampilan mendatang, atau kelas lain yang diikuti tidak dinyatakan dalam informasi yang diberikan.","id":"CPU05","kunci":2,"opsi":["Sari lulus ujian dasar pada pekan ini.","Sari mengikuti lebih dari satu kelas tari lanjutan hari ini.","Sari sudah lulus ujian dasar dan membawa kostum latihan.","Sari akan tampil dalam pertunjukan sanggar bulan depan.","Sari hari ini hanya mengikuti kelas tari lanjutan dan tidak mengikuti kelas lain."],"soal":"Di sebuah sanggar tari berlaku aturan: setiap peserta yang mengikuti kelas tari lanjutan harus sudah lulus ujian dasar dan membawa kostum latihan. Hari ini Sari mengikuti kelas tari lanjutan di sanggar tersebut. Manakah kesimpulan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Nama hari, nama bulan, nama daerah, dan nama museum ditulis dengan huruf kapital. Hanya kalimat tentang kunjungan museum yang mengikuti seluruh kaidah tersebut; kalimat lain menulis nama hari, nama bulan, atau nama daerah dengan huruf kecil.","id":"CPPU01","kunci":4,"opsi":["Mereka berlatih tari setiap hari senin di balai desa.","Festival budaya itu dibuka pada bulan agustus di alun-alun kota.","Tim kesenian dari yogyakarta tampil pada acara penutupan.","Para peserta berasal dari jawa barat dan bali.","Mereka mengunjungi Museum Sonobudoyo di Yogyakarta pada hari Minggu."],"soal":"Dari lima kalimat berikut, kalimat manakah yang menerapkan huruf kapital sesuai EYD Edisi Kelima?","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Mahkamah Konstitusi berwenang menguji undang-undang terhadap Undang-Undang Dasar Negara Republik Indonesia Tahun 1945. Mahkamah Agung menguji peraturan perundang-undangan di bawah undang-undang, Dewan Perwakilan Rakyat membentuk undang-undang bersama Presiden, Komisi Yudisial mengawasi perilaku hakim, dan Badan Pemeriksa Keuangan memeriksa pengelolaan keuangan negara.","id":"CPPU02","kunci":0,"opsi":["Mahkamah Konstitusi","Mahkamah Agung","Dewan Perwakilan Rakyat","Komisi Yudisial","Badan Pemeriksa Keuangan"],"soal":"Lembaga negara yang berwenang menguji undang-undang terhadap Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 adalah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Puncak Jaya di Pegunungan Tengah Papua merupakan titik tertinggi di Indonesia. Gunung Semeru merupakan titik tertinggi di Pulau Jawa, Gunung Kerinci merupakan titik tertinggi di Pulau Sumatera, sedangkan Gunung Rinjani dan Gunung Merapi lebih rendah daripada Puncak Jaya.","id":"CPPU03","kunci":2,"opsi":["Gunung Semeru","Gunung Kerinci","Puncak Jaya","Gunung Rinjani","Gunung Merapi"],"soal":"Gunung tertinggi di Indonesia adalah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Menguap adalah perubahan wujud dari cair menjadi gas. Mengembun adalah perubahan wujud dari gas menjadi cair, membeku adalah perubahan wujud dari cair menjadi padat, mencair adalah perubahan wujud dari padat menjadi cair, dan menyublim adalah perubahan wujud dari padat menjadi gas.","id":"CPPU04","kunci":1,"opsi":["Mengembun","Menguap","Membeku","Mencair","Menyublim"],"soal":"Perubahan wujud zat dari cair menjadi gas disebut ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Angklung merupakan alat musik bambu masyarakat Sunda dari Jawa Barat yang dibunyikan dengan cara digoyangkan. Daerah lain yang disebutkan memiliki alat musik tradisional yang berbeda.","id":"CPPU05","kunci":3,"opsi":["Bali","Sumatera Utara","Kalimantan Timur","Jawa Barat","Nusa Tenggara Timur"],"soal":"Alat musik tradisional angklung, yang terbuat dari bambu dan dibunyikan dengan cara digoyangkan, berasal dari daerah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Bacaan menggambarkan liga sebagai ruang olahraga yang membuat warga lebih aktif bergerak, kegiatan positif bagi remaja, sarana mempererat hubungan antarkampung, serta kesempatan bagi panitia untuk mengumumkan kegiatan desa dan mengumpulkan dana perbaikan lapangan. Gagasan tersebut dirangkum dalam manfaat olahraga, pertemuan, dan gotong royong. Pernyataan lain hanya mencakup sebagian isi bacaan, membatasi fungsi lapangan, atau bertentangan dengan pernyataan bahwa pertandingan bukan hanya soal mencetak gol.","id":"CPBM01","kunci":0,"opsi":["Liga sepak bola mini antarkampung memberi manfaat olahraga, pertemuan, dan gotong royong bagi warga.","Lapangan rumput di pinggir desa hanya cocok dipakai untuk pertandingan sepak bola mini.","Remaja desa membutuhkan kegiatan positif agar tidak menghabiskan akhir pekan tanpa kegiatan.","Panitia liga sebaiknya mengumumkan kegiatan desa pada setiap jeda pertandingan.","Pertandingan sepak bola mini hanya penting untuk menentukan tim yang mencetak gol terbanyak."],"soal":"Setiap akhir pekan, lapangan rumput di pinggir desa berubah menjadi arena liga sepak bola mini antarkampung. Tim-tim yang terdiri atas pemuda, petani, dan pegawai desa bertanding dalam suasana santai, sementara warga menonton sambil membawa bekal dari rumah. Pertandingan ini bukan hanya soal mencetak gol. Kegiatan rutin ini membuat warga lebih aktif bergerak, memberi kegiatan positif bagi remaja, dan mempererat hubungan antarkampung yang sebelumnya jarang bertemu. Panitia juga memanfaatkan jeda pertandingan untuk mengumumkan kegiatan desa dan mengumpulkan dana bagi perbaikan lapangan. Dengan demikian, liga kecil ini menjadi ruang olahraga, pertemuan, dan gotong royong bagi seluruh warga. Gagasan utama bacaan tersebut adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Nelayan menunda keberangkatan ketika gelombang diperkirakan tinggi, jumlah perahu yang kembali lebih awal karena cuaca buruk menurun, dan tidak ada perahu yang terjebak badai dalam satu musim. Catatan hasil tangkapan membantu membandingkan hari yang aman dengan hari yang berisiko. Rangkaian fakta tersebut menunjukkan informasi cuaca membantu nelayan bekerja lebih aman dan terencana. Bacaan tidak menyatakan semua nelayan terbebas dari cuaca buruk, tidak membandingkan papan pengumuman dengan pengalaman nelayan, tidak menyatakan hasil tangkapan selalu meningkat, dan tidak menyatakan ketua kelompok sebagai satu-satunya pihak yang memahami prakiraan.","id":"CPBM02","kunci":2,"opsi":["Semua nelayan di desa itu kini tidak pernah lagi menghadapi cuaca buruk di laut.","Papan pengumuman cuaca lebih penting daripada pengalaman nelayan dalam membaca tanda alam.","Memeriksa informasi cuaca sebelum melaut membantu nelayan bekerja lebih aman dan terencana.","Hasil tangkapan nelayan selalu meningkat setiap kali mereka menunda keberangkatan.","Ketua kelompok adalah satu-satunya nelayan yang memahami prakiraan angin dan gelombang."],"soal":"Kelompok nelayan di sebuah desa pesisir mulai memeriksa informasi cuaca sebelum melaut. Setiap sore, ketua kelompok membaca prakiraan angin dan tinggi gelombang dari papan pengumuman, lalu menyampaikan hasilnya kepada anggota melalui pengeras suara. Nelayan yang semula berangkat berdasarkan kebiasaan kini menunda keberangkatan ketika gelombang diperkirakan tinggi. Dalam satu musim, jumlah perahu yang kembali lebih awal karena cuaca buruk menurun, dan tidak ada perahu yang terjebak badai di tengah laut. Para nelayan juga mencatat hasil tangkapan setiap hari agar dapat membandingkan hari yang aman dengan hari yang berisiko. Kebiasaan sederhana ini membantu mereka bekerja dengan lebih tenang dan terencana. Berdasarkan bacaan tersebut, dapat disimpulkan bahwa ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Dalam konteks bacaan, syukuran panen tidak lagi dipandang sebagai kewajiban, melainkan sebagai pertemuan yang dinantikan, dan para perantau berusaha pulang untuk menghadirinya. Keadaan tersebut menunjukkan kebiasaan yang sudah kuat dan menyatu dalam kehidupan warga. Makna tumbuhan berakar secara harfiah, penyebaran ke desa lain, kebiasaan yang ditinggalkan, atau pengaturan melalui aturan tertulis tidak sesuai dengan isi bacaan.","id":"CPBM03","kunci":4,"opsi":["tumbuh sebagai tanaman yang berakar di dalam tanah","menyebar dengan cepat ke desa-desa tetangga","ditinggalkan secara perlahan oleh warga desa","diatur secara ketat oleh aturan tertulis desa","menjadi kebiasaan yang kuat dan sudah menyatu dalam kehidupan warga"],"soal":"Di Desa Sumberrejo, syukuran panen diadakan setiap kali musim panen tiba. Warga membawa hasil bumi ke balai desa, lalu memasak bersama dan membagikan makanan kepada tetangga. Anak-anak ikut membantu menyiapkan hidangan sederhana, sementara orang tua menceritakan cara menanam padi pada masa lalu. Kegiatan ini telah mengakar di kalangan warga sehingga tidak lagi dipandang sebagai kewajiban, melainkan sebagai pertemuan yang dinantikan. Para perantau pun berusaha pulang pada hari syukuran agar dapat berkumpul dengan keluarga. Dengan cara itu, syukuran panen menjaga hubungan warga dengan tanah, keluarga, dan sesama tetangga dari tahun ke tahun. Kata 'mengakar' dalam bacaan tersebut bermakna ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kalimat terakhir mengulang kata latihan, menggabungkan penanda sangat dan sekali, serta menambahkan keterangan yang tidak perlu tentang bulu tangkis yang dimainkan. Kalimat yang efektif menyampaikan gagasan yang sama secara ringkas dengan susunan yang jelas, tanpa pengulangan kata dan tanpa penanda penguat ganda: latihan membuat pemain lebih disiplin dan terampil dalam bermain bulu tangkis. Susunan lain masih mempertahankan pengulangan kata, penguat ganda, atau keterangan yang bertele-tele sehingga tetap tidak efektif.","id":"CPBM04","kunci":1,"opsi":["Latihan ini sangat bermanfaat sekali karena latihan ini membuat para pemain menjadi lebih disiplin dan lebih terampil dalam bermain bulu tangkis yang mereka mainkan.","Latihan ini membuat pemain lebih disiplin dan terampil dalam bermain bulu tangkis.","Latihan yang sangat bermanfaat sekali ini adalah latihan yang membuat para pemain menjadi lebih disiplin dan lebih terampil dalam bermain bulu tangkis.","Latihan ini adalah latihan yang bermanfaat karena para pemain menjadi lebih disiplin dan lebih terampil dalam bermain bulu tangkis yang mereka mainkan setiap pekan.","Latihan ini membuat para pemain menjadi lebih disiplin dan lebih terampil dalam bermain bulu tangkis yang sangat bermanfaat sekali bagi mereka."],"soal":"Klub bulu tangkis Sekolah Pelita Bangsa berlatih tiga kali setiap pekan di aula sekolah. Pelatih membagi peserta ke dalam kelompok kecil agar setiap pemain mendapat giliran bermain dan umpan balik yang cukup. Peserta pemula berlatih pukulan dasar dan gerak kaki, sedangkan peserta yang lebih mahir berlatih strategi ganda dan pengembalian cepat. Setiap akhir bulan, pelatih mengadakan pertandingan persahabatan antarkelompok untuk mengukur kemajuan peserta. Latihan ini adalah latihan yang sangat bermanfaat sekali karena latihan ini membuat para pemain menjadi lebih disiplin dan lebih terampil dalam bermain bulu tangkis yang mereka mainkan. Kalimat terakhir bacaan tersebut tidak efektif karena bertele-tele. Perbaikan kalimat yang paling efektif adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Awalan di pada kata kerja pasif ditulis serangkai dengan kata dasarnya sehingga bentuk yang tepat adalah diselenggarakan. Nama bulan ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Oktober. Kata ulang ditulis dengan tanda hubung sehingga bentuk yang tepat adalah anak-anak. Bentuk yang memenuhi seluruh kaidah tersebut adalah kalimat dengan diselenggarakan, Oktober, dan anak-anak.","id":"CPBM05","kunci":3,"opsi":["Lomba ini di selenggarakan setiap bulan oktober dan diikuti oleh peserta dewasa dan anak anak.","Lomba ini diselenggarakan setiap bulan oktober dan diikuti oleh peserta dewasa dan anak-anak.","Lomba ini di selenggarakan setiap bulan Oktober dan diikuti oleh peserta dewasa dan anak-anak.","Lomba ini diselenggarakan setiap bulan Oktober dan diikuti oleh peserta dewasa dan anak-anak.","Lomba ini diselenggarakan setiap bulan Oktober dan diikuti oleh peserta dewasa dan anak anak."],"soal":"(1) Festival layang-layang tahunan kembali digelar di tepi pantai selatan. (2) Peserta datang dari berbagai daerah dengan layang-layang berbentuk burung, ikan, dan tokoh pewayangan. (3) Lomba ini di selenggarakan setiap bulan oktober dan diikuti oleh peserta dewasa dan anak anak. (4) Penonton dapat menyaksikan layang-layang raksasa yang diterbangkan oleh tim dari beberapa sanggar seni. (5) Panitia berharap festival ini memperkenalkan permainan tradisional kepada generasi muda. Perbaikan kalimat (3) sesuai EYD Edisi Kelima adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Persediaan awal adalah 360 meter. Pemakaian 25% dari 360 meter adalah 90 meter sehingga sisanya menjadi 270 meter. Pemakaian 20% dihitung dari 270 meter, yaitu 54 meter, sehingga sisa akhir adalah 270 meter dikurangi 54 meter, yaitu 216 meter. Pemakaian tahap akhir tidak dihitung dari persediaan awal sehingga persen pada tiap tahap tidak dapat dijumlahkan begitu saja.","id":"CPK01","kunci":2,"opsi":["180 meter","198 meter","216 meter","234 meter","270 meter"],"soal":"Persediaan kain sebuah sanggar adalah 360 meter. Sebanyak 25% dari persediaan itu dipakai untuk membuat kostum, kemudian 20% dari sisa kain dipakai untuk membuat dekorasi panggung. Berapa meter kain yang tersisa?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Selisih perbandingan adalah 5 dikurangi 3, yaitu 2 bagian, dan selisih tersebut setara dengan 120 gram sehingga satu bagian setara dengan 60 gram. Jumlah perbandingan adalah 5 ditambah 3, yaitu 8 bagian, sehingga jumlah tepung dan gula adalah 8 dikali 60 gram, yaitu 480 gram. Sebagai pemeriksaan, tepung adalah 300 gram dan gula adalah 180 gram, dengan selisih 120 gram.","id":"CPK02","kunci":4,"opsi":["420 gram","450 gram","540 gram","600 gram","480 gram"],"soal":"Perbandingan banyak tepung dan gula dalam sebuah resep adalah 5:3. Selisih banyak tepung dan gula adalah 120 gram. Berapa jumlah tepung dan gula dalam resep tersebut?","subtes":"Pengetahuan Kuantitatif"},{"id":"CPK03","subtes":"Pengetahuan Kuantitatif","soal":"Perhatikan barisan bilangan berikut: 5, 12, 23, 38, 57, ... Bilangan berikutnya dalam barisan tersebut adalah ...","opsi":["76","80","84","78","82"],"kunci":1,"bahas":"Selisih antarbilangan yang berurutan adalah 7, 11, 15, dan 19, sehingga selisih bertambah 4 setiap langkah. Selisih berikutnya adalah 23 sehingga bilangan berikutnya adalah 57 ditambah 23, yaitu 80."},{"bahas":"Diameter 14 meter berarti jari-jari lingkaran adalah 7 meter. Luas lingkaran dihitung dengan π dikali kuadrat jari-jari sehingga luasnya adalah 22/7 dikali 49, yaitu 154 m². Hasil 44 m² berasal dari keliling lingkaran, hasil 308 m² adalah dua kali luas yang benar, dan hasil 616 m² berasal dari pemakaian diameter sebagai jari-jari.","id":"CPK04","kunci":3,"opsi":["44 m²","88 m²","308 m²","154 m²","616 m²"],"soal":"Sebuah panggung pertunjukan berbentuk lingkaran memiliki diameter 14 meter. Dengan π = 22/7, berapa luas panggung tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Jumlah curah hujan selama lima hari adalah 12 + 18 + 15 + 20 + 15 = 80 mm. Rata-rata curah hujan per hari diperoleh dengan membagi 80 mm dengan 5, yaitu 16 mm.","id":"CPK05","kunci":0,"opsi":["16 mm","15 mm","17 mm","18 mm","14 mm"],"soal":"Curah hujan di sebuah desa selama lima hari berturut-turut tercatat 12 mm, 18 mm, 15 mm, 20 mm, dan 15 mm. Berapa rata-rata curah hujan per hari selama lima hari tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Teks menceritakan remaja dan lansia yang bertemu dalam kelas memasak: lansia mengajarkan resep yang selama ini hanya dihafal, remaja mencatat dan menuliskan resep dalam buku kecil, dan buku resep dibagikan kepada warga agar masakan daerah tetap dikenal. Gagasan utama mencakup penjagaan resep daerah dan ruang belajar bagi remaja, bukan hanya satu rincian atau perbandingan kemampuan yang tidak dinyatakan teks.","id":"CLBI01","kunci":3,"opsi":["Remaja masa kini tidak lagi mengenal masakan daerah dari keluarganya.","Buku resep kecil adalah satu-satunya cara menjaga masakan daerah agar tidak hilang.","Para lansia lebih mahir memasak daripada remaja dalam segala hal.","Kelas memasak bersama lansia menjaga resep daerah sekaligus menjadi ruang belajar bagi remaja.","Makan bersama di akhir kelas bertujuan menilai masakan peserta secara jujur."],"soal":"Di sebuah balai warga, kelas memasak mempertemukan remaja dengan para lansia setiap bulan. Para lansia mengajarkan resep masakan daerah yang selama ini hanya dihafal, sementara remaja mencatat takaran, memotret setiap tahap, dan menuliskan resep itu dalam buku kecil. Kegiatan ini membuat resep lama tidak hilang bersama ingatan, sekaligus memberi ruang bagi remaja untuk belajar langsung dari pengalaman. Di akhir kelas, semua peserta makan bersama dan saling menilai hasil masakan dengan jujur. Buku resep yang terkumpul kemudian dibagikan kepada warga agar masakan daerah tetap dikenal dan dapat dimasak kembali di rumah masing-masing. Apa gagasan utama teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan hujan sering bergeser sehingga masa berbunga ikut berubah, dan petani menanam pohon pelindung, memperbaiki saluran air, menunda pemangkasan, serta bertukar catatan dengan petani desa tetangga. Teks juga menegaskan langkah tersebut tidak mengubah cuaca, melainkan membantu petani mengambil keputusan berdasarkan pengamatan. Pernyataan yang sesuai adalah penyesuaian cara berkebun dengan pengamatan terhadap perubahan musim.","id":"CLBI02","kunci":1,"opsi":["Hujan di dataran tinggi selalu datang pada waktu yang sama setiap tahun.","Petani menyesuaikan cara berkebun dengan pengamatan terhadap perubahan musim.","Menanam pohon pelindung dapat mengubah pola hujan di dataran tinggi.","Semua petani kopi telah meninggalkan kebiasaan lama dalam berkebun.","Pemangkasan tanaman kopi sebaiknya dilakukan sebelum hujan turun."],"soal":"Para petani kopi di dataran tinggi mulai mencatat perubahan musim tanam dengan lebih cermat. Hujan yang dahulu datang pada waktu yang hampir sama setiap tahun kini sering bergeser, sehingga masa berbunga tanaman kopi ikut berubah. Untuk menyesuaikan diri, petani menanam pohon pelindung agar tanaman tidak terlalu panas, memperbaiki saluran air di kebun, dan menunda pemangkasan ketika hujan belum turun. Mereka juga bertukar catatan dengan petani dari desa tetangga agar dapat membandingkan kondisi kebun masing-masing. Langkah-langkah ini tidak mengubah cuaca, tetapi membantu petani mengambil keputusan berdasarkan pengamatan, bukan sekadar kebiasaan lama. Berdasarkan teks, pernyataan manakah yang sesuai dengan isi teks?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menceritakan keraguan anggota terhadap cerita rakyat, diskusi ulang tentang tokoh cerita, latihan yang berubah menjadi perdebatan tentang keputusan tokoh, dan penonton remaja yang tertawa dan terdiam seolah cerita itu bercerita tentang mereka sendiri. Rangkaian peristiwa tersebut menunjukkan cerita rakyat dapat terasa dekat bagi remaja bila maknanya digali bersama. Teks tidak menyajikan jadwal, tidak membandingkan cerita rakyat dengan cerita modern, tidak mengajak semua kelompok melakukan hal yang sama, dan tidak menempatkan hafalan dialog sebagai bagian terpenting.","id":"CLBI03","kunci":4,"opsi":["Menjelaskan jadwal latihan dan pementasan tahunan kelompok teater remaja.","Membandingkan cerita rakyat dengan cerita modern yang disukai remaja.","Mengajak semua kelompok teater remaja mementaskan cerita rakyat setiap tahun.","Menunjukkan bahwa hafalan dialog adalah bagian terpenting dalam latihan teater.","Menunjukkan bahwa cerita rakyat dapat terasa dekat bagi remaja bila digali maknanya bersama."],"soal":"Kelompok teater remaja di sebuah kota kecil memilih cerita rakyat sebagai bahan pementasan tahunan mereka. Awalnya, sebagian anggota ragu karena menganggap cerita lama membosankan bagi penonton seusia mereka. Sutradara muda kelompok itu kemudian mengajak anggota mendiskusikan ulang tokoh-tokoh cerita: apa yang membuat tokoh itu berani, apa yang membuatnya takut, dan pilihan apa yang dihadapinya. Latihan pun berubah menjadi perdebatan seru tentang keputusan tokoh, bukan sekadar hafalan dialog. Pada malam pementasan, penonton remaja tertawa dan terdiam pada bagian yang sama, seolah cerita itu bercerita tentang mereka sendiri. Apa tujuan penulis menyajikan kisah kelompok teater tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Dian tidak menjadi juara pada lomba yang sama, tetapi waktu tempuhnya lebih cepat dan ia tersenyum saat melewati garis akhir setelah berlatih dengan tekun selama tiga bulan. Rangkaian peristiwa tersebut menyiratkan kemajuan pribadi dan ketekunan berlatih sebagai ukuran keberhasilan, bukan hanya gelar juara. Menempel nomor dada, anggapan tentang kegagalan yang menetap, anggapan bahwa latihan selalu menghasilkan gelar juara, atau anggapan tentang satu-satunya cara memperbaiki waktu tempuh tidak didukung oleh isi teks.","id":"CLBI04","kunci":0,"opsi":["Kemajuan pribadi dan ketekunan berlatih dapat menjadi ukuran keberhasilan, bukan hanya gelar juara.","Menempelkan nomor dada di dinding kamar membuat pelari menjadi lebih cepat.","Pelari yang tidak menjadi juara pada lomba pertama tidak akan pernah berhasil.","Berlatih setiap pagi sebelum sekolah selalu menghasilkan gelar juara pada lomba berikutnya.","Mencatat waktu lari adalah satu-satunya cara untuk memperbaiki waktu tempuh pelari."],"soal":"Dian pulang dari lomba lari pertama tanpa membawa pulang medali. Di rumah, ia menempelkan nomor dadanya di dinding kamar, tepat di samping jadwal latihan yang ia susun sendiri. Setiap pagi sebelum sekolah, ia berlari mengelilingi lapangan desa, menambah satu putaran setiap pekan. Ia juga mulai mencatat waktu larinya di buku kecil dan memperhatikan cara pelari yang lebih cepat mengatur napas. Tiga bulan kemudian, Dian kembali mengikuti lomba yang sama. Ia tidak menjadi juara, tetapi waktu tempuhnya lebih cepat dan ia tersenyum saat melewati garis akhir. Apa makna tersirat dari kisah Dian dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pendapat penolak hanya melihat kesukaan sesaat dan mengabaikan apa yang hilang bila permainan tradisional ditinggalkan, lalu menjelaskan permainan tradisional melatih gerak tubuh, kerja sama, dan ketahanan menghadapi kekalahan, serta membawa cerita dan nilai kebersamaan. Kelemahannya terletak pada penilaian yang hanya berdasarkan kesukaan sesaat dan mengabaikan manfaat yang hilang.","id":"CLBI05","kunci":2,"opsi":["Anggapan bahwa permainan digital tidak memiliki manfaat apa pun bagi anak-anak.","Keyakinan bahwa semua anak menyukai permainan digital dalam keadaan apa pun.","Penilaian yang hanya berdasarkan kesukaan sesaat dan mengabaikan manfaat yang hilang.","Gagasan bahwa sekolah sudah mengajarkan permainan tradisional dengan cara yang menarik.","Dugaan bahwa permainan tradisional hanya melatih gerak tubuh dan tidak membawa nilai kebersamaan."],"soal":"Sebagian orang berpendapat bahwa permainan tradisional tidak perlu lagi diajarkan di sekolah karena anak-anak lebih menyukai permainan digital. Pendapat ini hanya melihat kesukaan sesaat dan mengabaikan apa yang hilang bila permainan tradisional ditinggalkan. Permainan seperti gobak sodor dan lompat tali melatih gerak tubuh, kerja sama, dan ketahanan menghadapi kekalahan secara langsung, hal-hal yang tidak selalu didapat dari layar. Selain itu, permainan tradisional membawa cerita dan nilai kebersamaan dari daerah masing-masing. Menilai permainan hanya dari tingkat kesukaan sesaat berarti menilai manfaatnya secara tidak lengkap. Menurut teks, kelemahan pendapat yang menolak pengajaran permainan tradisional terletak pada ...","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menjelaskan klub lari mingguan yang anggotanya berasal dari berbagai usia, tidak dituntut berlari cepat, berlari pelan bersama, dan berkumpul untuk sarapan sederhana setelah berlari. Penyelenggara menegaskan klub ini bukan tentang balapan, melainkan tentang membangun kebiasaan, menikmati udara segar, dan memberi alasan bagi tetangga untuk menghabiskan waktu bersama. Gagasan utama mencakup seluruh gambaran tersebut, bukan hanya satu rincian atau pernyataan yang bertentangan dengan teks.","id":"CLBE01","kunci":1,"opsi":["Running fast is the most important goal of every running club.","A weekly running club helps neighbors build a healthy habit and spend time together.","Grandparents should always run with teenagers to stay safe on river routes.","Breakfast prepared by volunteers is the main reason people join the club.","Experienced runners must teach beginners how to win local races."],"soal":"Every Saturday morning, a running club meets at the edge of a small town. Members range from teenagers to grandparents, and nobody is asked to run fast. The group follows a slow route along the river, stops for water, and walks the last part together. New members are paired with experienced runners who explain how to breathe steadily and how to avoid injury. After the run, everyone gathers for a simple breakfast prepared by volunteers. The organizers say the club is not about racing. It is about building a habit, enjoying fresh air, and giving neighbors a reason to spend time together each week. What is the main idea of the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Kata tersebut menggambarkan bunyi-bunyi terpisah yang perlahan berubah menjadi satu melodi yang dapat diikuti semua orang setelah kelompok belajar saling mendengarkan. Gambaran tersebut menunjukkan penggabungan yang halus menjadi satu kesatuan, bukan bunyi yang menghilang, mengeras, terpisah, atau berhenti mendadak.","id":"CLBE02","kunci":4,"opsi":["disappear completely","become louder and stronger","separate into different parts","stop suddenly and sharply","combine smoothly into one"],"soal":"At a community center, a group of students learns to play angklung, a bamboo instrument from West Java. Each player holds one or two bamboo tubes and shakes them at the right moment. At first, the sounds come out unevenly, and the melody is hard to recognize. The teacher asks the group to listen to one another instead of playing louder. Slowly, the separate notes begin to blend into a single melody that everyone can follow. The students learn that the beauty of the music comes not from one player, but from many players working together at the right time. The word 'blend' in the passage is closest in meaning to ...","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan catatan cuaca semula hanya dipakai untuk tugas kelas, lalu petani meminta melihat catatan curah hujan, petani lain mengikuti, dan kelas memasang ringkasan mingguan di gerbang sekolah. Siswa terkejut bahwa tugas rutin mereka membantu tetangga merencanakan pekerjaan dan kini memeriksa alat dengan lebih cermat. Rangkaian fakta tersebut menunjukkan tugas sekolah yang sederhana menjadi berguna bagi masyarakat luas di luar kelas.","id":"CLBE03","kunci":2,"opsi":["The students built the weather station because farmers asked them to do it.","All farmers in the area now depend only on the school's weather records.","A simple school routine became useful to the wider community beyond the classroom.","The school gate summary replaced all other sources of weather information.","The students recorded weather data mainly to earn higher grades in science."],"soal":"A high school science class set up a simple weather station on the school roof. Every morning, two students recorded rainfall, wind direction, and temperature in a shared notebook. At first, the records were only used for class assignments. Then a farmer who lived near the school asked to see the rainfall notes before deciding when to plant rice. Other farmers soon followed, and the class began posting a weekly summary on the school gate. The students were surprised that their routine task helped neighbors plan their work. They now check the instruments more carefully, knowing that someone outside the school relies on their notes. What can be inferred from the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan juri berpendapat aturan tersebut mendorong juru masak muda belajar langsung dari kerabat yang lebih tua sebelum perlombaan dimulai. Alasan tersebut berkaitan dengan cara belajar dari kerabat yang lebih tua, bukan dengan jenis hidangan pemenang, larangan bantuan kerabat, jumlah latihan pemenang, atau anggapan bahwa hidangan tradisional terlalu sulit dipelajari.","id":"CLBE04","kunci":0,"opsi":["To encourage young cooks to learn traditional dishes directly from older relatives.","To make sure that contestants cook only fish soup in every contest.","To prevent older relatives from helping contestants during the contest.","To test whether contestants can remember exactly five practice attempts.","To show that traditional dishes are too difficult for young cooks to learn."],"soal":"Once a year, a coastal town holds a cooking contest with one unusual rule: contestants must cook a traditional dish from memory, without written recipes or phones. Judges say the rule encourages young cooks to learn directly from older relatives before the contest begins. Last year, twenty contestants cooked dishes they had learned from grandparents, parents, or neighbors. Some forgot a step and had to improvise, while others recalled flavors they had not tasted for years. The winner, a seventeen-year-old student, cooked a fish soup her grandmother used to make. She said she had practiced the dish five times at home, tasting it with her grandmother after each attempt. According to the passage, why does the contest forbid written recipes and phones?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menceritakan Hartini yang mulai belajar berenang pada usia enam puluh tahun, mengalami kesulitan pada awal pelajaran, berlatih sedikit demi sedikit tanpa dikejar waktu, dan akhirnya berenang satu panjang kolam tanpa berhenti. Cerita tersebut menggambarkan ketakutan yang diatasi secara perlahan dan belajar keterampilan baru yang tidak dibatasi usia, bukan keunggulan satu cabang olahraga, teknik berenang, belajar tanpa instruktur, atau anggapan bahwa semua orang mencapai hasil yang sama dalam waktu yang sama.","id":"CLBE05","kunci":3,"opsi":["To argue that swimming is the best sport for older adults in every case.","To explain the correct technique for floating and moving arms in swimming.","To suggest that older adults should learn to swim without an instructor.","To show that fear can be overcome slowly and that learning a new skill has no age limit.","To claim that every older adult will swim a full length within six months."],"soal":"At sixty, Mrs. Hartini decided to learn to swim after a lifetime of watching others from the poolside. Her first lessons were difficult. She held the pool edge tightly, swallowed water, and often left the pool feeling tired and embarrassed. Her instructor, however, never rushed her. Each week, Mrs. Hartini practiced floating a little longer and moving her arms more calmly. After six months, she swam one full length of the pool without stopping. She now joins a morning swimming group and encourages other older adults to try. She says the water taught her that fear shrinks when it is faced slowly, one small step at a time. What is the author's purpose in telling Mrs. Hartini's story?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Dalam 3 hari, 6 penjahit menyelesaikan 54 kostum, sehingga satu penjahit menyelesaikan 3 kostum dalam 1 hari. Untuk 9 penjahit selama 4 hari: 9 dikali 4 dikali 3 sama dengan 108 kostum.","id":"CPM01","kunci":4,"opsi":["90","96","102","120","108"],"soal":"Sebuah sanggar tari memesan kostum kepada 6 penjahit yang bekerja dengan laju sama. Keenam penjahit tersebut menyelesaikan 54 kostum dalam 3 hari. Jika jumlah penjahit ditambah menjadi 9 orang dan semuanya bekerja selama 4 hari dengan laju yang sama, berapa kostum yang dapat diselesaikan?","subtes":"Penalaran Matematika"},{"bahas":"Selisih antara bilangan yang berurutan adalah 2, 4, 8, dan 16, sehingga selisih berlipat dua setiap langkah. Selisih berikutnya adalah 32 sehingga bilangan berikutnya adalah 35 ditambah 32, yaitu 67.","id":"CPM02","kunci":2,"opsi":["59","63","67","71","75"],"soal":"Perhatikan barisan bilangan berikut: 5, 7, 11, 19, 35, ... Bilangan berikutnya dalam barisan tersebut adalah ....","subtes":"Penalaran Matematika"},{"bahas":"Jumlah gol dalam delapan pertandingan adalah 1 + 2 + 2 + 3 + 3 + 3 + 4 + 6 = 24, sehingga rata-rata gol per pertandingan adalah 24 dibagi 8, yaitu 3. Gol yang melebihi rata-rata hanya terjadi pada pertandingan dengan 4 gol dan pertandingan dengan 6 gol, yaitu 2 pertandingan.","id":"CPM03","kunci":0,"opsi":["2 pertandingan","3 pertandingan","4 pertandingan","5 pertandingan","1 pertandingan"],"soal":"Jumlah gol yang dicetak sebuah tim dalam 8 pertandingan berturut-turut adalah sebagai berikut: 1, 2, 2, 3, 3, 3, 4, 6. Pada berapa pertandingan jumlah gol yang dicetak melebihi rata-rata gol per pertandingan?","subtes":"Penalaran Matematika"},{"bahas":"Peluang mendapat kartu bergambar matahari pada pengambilan awal adalah 6 dari 10. Setelah satu kartu bergambar matahari terambil tanpa pengembalian, tersisa 5 kartu bergambar matahari dari 9 kartu. Mengalikan peluang tersebut: 6/10 dikali 5/9 sama dengan 30/90, yaitu 1/3.","id":"CPM04","kunci":3,"opsi":["3/10","1/4","2/5","1/3","1/5"],"soal":"Setumpuk kartu terdiri atas 6 kartu bergambar matahari dan 4 kartu bergambar bulan. Dua kartu diambil satu demi satu secara acak tanpa pengembalian. Peluang bahwa dua kartu yang terambil keduanya bergambar matahari adalah ....","subtes":"Penalaran Matematika"},{"bahas":"Sebanyak 60% dari 200 peserta adalah 120 peserta yang lolos dari tahap awal. Sebanyak 25% dari 120 peserta adalah 30 peserta yang lolos ke babak final. Persen tahap akhir dihitung dari peserta yang lolos tahap awal, bukan dari seluruh peserta.","id":"CPM05","kunci":1,"opsi":["24","30","36","45","50"],"soal":"Sebuah kompetisi menyaring 200 peserta melalui dua tahap. Sebanyak 60% peserta lolos dari tahap awal, dan 25% dari peserta yang lolos tahap awal lolos ke babak final. Berapa peserta yang lolos ke babak final?","subtes":"Penalaran Matematika"}];
